#####################################################################################
# Project: 16S rRNA Metabarcoding
# Script: 02_dada2_QC.R
# Author: Gustavo Goncalves
# Last edit: 03/11/2026
#
# Description:
# Quality control report for 01_dada2_asv_inference.R
#
# Notes:
#   This script requires the objects generated by 01_dada2_asv_inference.R.
#
#   Remember to load the config.R file for the specific project before running
#   this script. For example:
#       source("projects/coffee/config.R")
#####################################################################################

# Set up packages
library(dada2); packageVersion("dada2")
library(ggplot2); packageVersion("ggplot2")

theme_set(theme_bw())

# Create QC directory
qc_path <- file.path(results_path, "dada2-QC")
dir.create(qc_path, recursive = TRUE, showWarnings = FALSE)

# Load objects
objects_dir <- file.path(project_path, "results", "objects")

dadaFs            <- readRDS(file.path(objects_dir, "dadaFs.rds"))
dadaRs            <- readRDS(file.path(objects_dir, "dadaRs.rds"))
errF              <- readRDS(file.path(objects_dir, "errF.rds"))
errR              <- readRDS(file.path(objects_dir, "errR.rds"))
filterAndTrim_out <- readRDS(file.path(objects_dir, "filterAndTrim_out.rds"))
seqtab            <- readRDS(file.path(objects_dir, "seqtab.rds"))
seqtab.nochim     <- readRDS(file.path(objects_dir, "seqtab-nochim.rds"))
taxa          <- readRDS(file.path(objects_dir, "taxonomy.rds"))
track <- read.csv(file.path(project_path, "results", "read_tracking.csv"), row.names = 1)

#####################################################################################
# QC calculations
#####################################################################################

# General information
n_samples <- nrow(seqtab.nochim)
n_asvs <- ncol(seqtab.nochim)

reads <- rowSums(seqtab.nochim)

mean_reads <- mean(reads)
median_reads <- median(reads)

# Read retention
track$Retention <- round(
  100 * track$nonchim / track$input,
  2
)

retention_summary <- summary(track$Retention)
mean_retention <- mean(track$Retention)
median_retention <- median(track$Retention)

# ASVs per sample
asvs <- apply(seqtab.nochim > 0, 1, sum)

# ASV abundance
abundance <- colSums(seqtab.nochim)

# ASV lengths
lengths <- nchar(
  getSequences(seqtab.nochim)
)

# Reads from ASVs shorter than the expected minimum ASV length
reads_short <- sum(
  abundance[lengths < expected_min_asv_length]
)

percent_reads_short <- 100 *
  reads_short / sum(abundance)

# Taxonomy
assigned <- colSums(!is.na(taxa))

assigned_percent <- round(
  100 * assigned / nrow(taxa),
  2
)

phylum <- sort(
  table(taxa[, "Phylum"]),
  decreasing = TRUE
)

family <- sort(
  table(taxa[, "Family"]),
  decreasing = TRUE
)


#####################################################################################
# Visual QC
#####################################################################################

# Read retention
p_retention <- ggplot(
  track,
  aes(y = Retention)
) +
  geom_boxplot() +
  labs(
    y = "Read retention (%)",
    x = NULL
  )

print(p_retention)

ggsave(
  file.path(qc_path, "01_read_retention.png"),
  plot = p_retention,
  width = 6,
  height = 5,
  dpi = 300
)

# ASVs per sample
p_asvs <- ggplot(
  data.frame(
    Sample = names(asvs),
    ASVs = asvs
  ),
  aes(Sample, ASVs)
) +
  geom_col() +
  coord_flip() +
  labs(
    x = "Sample",
    y = "Number of ASVs"
  )

print(p_asvs)

ggsave(
  file.path(qc_path, "02_asvs_per_sample.png"),
  plot = p_asvs,
  width = 8,
  height = 10,
  dpi = 300
)

# ASV abundance
hist(
  log10(abundance),
  breaks = 50,
  main = "ASV abundance distribution",
  xlab = "Log10 ASV abundance"
)

png(
  file.path(qc_path, "03_asv_abundance.png"),
  width = 1800,
  height = 1500,
  res = 300
)

hist(
  log10(abundance),
  breaks = 50,
  main = "ASV abundance distribution",
  xlab = "Log10 ASV abundance"
)

dev.off()

# ASV lengths
hist(
  lengths,
  breaks = 200,
  main = "ASV length distribution",
  xlab = "ASV length (bp)"
)

png(
  file.path(qc_path, "04_asv_lengths.png"),
  width = 1800,
  height = 1500,
  res = 300
)

hist(
  lengths,
  breaks = 200,
  main = "ASV length distribution",
  xlab = "ASV length (bp)"
)

dev.off()

# Phyla with highest number of ASVs
phylum_top20 <- head(phylum, 20)

p_phylum <- ggplot(
  data.frame(
    Phylum = names(phylum_top20),
    Count = as.numeric(phylum_top20)
  ),
  aes(
    x = reorder(Phylum, Count),
    y = Count
  )
) +
  geom_col() +
  coord_flip() +
  labs(
    x = "Phylum",
    y = "Number of ASVs"
  )

print(p_phylum)

ggsave(
  file.path(qc_path, "05_top20_phyla.png"),
  plot = p_phylum,
  width = 9,
  height = 7,
  dpi = 300
)

# Families with highest number of ASVs
family_top20 <- head(family, 20)

p_family <- ggplot(
  data.frame(
    Family = names(family_top20),
    Count = as.numeric(family_top20)
  ),
  aes(
    x = reorder(Family, Count),
    y = Count
  )
) +
  geom_col() +
  coord_flip() +
  labs(
    x = "Family",
    y = "Number of ASVs"
  )

print(p_family)

ggsave(
  file.path(qc_path, "06_top20_families.png"),
  plot = p_family,
  width = 9,
  height = 7,
  dpi = 300
)

#####################################################################################
# Detect possible problematic samples
#####################################################################################

cat("Samples with <30% retention:\n")

track[
  track$Retention < 30,
  c("input", "nonchim", "Retention")
]

cat("\nSamples with <1000 ASVs:\n")

asvs[asvs < 1000]

cat("\nSamples with <10000 reads:\n")

reads[reads < 10000]


#####################################################################################
# Save QC summary report
#####################################################################################

sink(
  file.path(
    qc_path,
    "dada2_QC_summary.txt"
  )
)

cat("=====================================\n")
cat("DADA2 QC SUMMARY REPORT\n")
cat("Project:", project_name, "\n")
cat("16S rRNA metabarcoding\n")
cat("=====================================\n\n")

cat("Generated:", format(Sys.time()), "\n\n")


# General information
cat("-------------------------------------\n")
cat("GENERAL INFORMATION\n")
cat("-------------------------------------\n\n")

cat("Number of samples:", n_samples, "\n")
cat("Total ASVs:", n_asvs, "\n")
cat("Total reads:", sum(reads), "\n")
cat("Mean reads/sample:", round(mean_reads), "\n")
cat("Median reads/sample:", round(median_reads), "\n\n")


# Read retention
cat("-------------------------------------\n")
cat("READ RETENTION\n")
cat("-------------------------------------\n\n")

cat("Retention summary (%):\n")
print(retention_summary)

cat(
  "\nMean retention (%):",
  round(mean_retention, 2),
  "\n"
)

cat(
  "Median retention (%):",
  round(median_retention, 2),
  "\n\n"
)


# Problematic samples
cat("-------------------------------------\n")
cat("POSSIBLE PROBLEMATIC SAMPLES\n")
cat("-------------------------------------\n\n")

cat("Samples with <30% retention:\n")

print(
  track[
    track$Retention < 30,
    c("input", "nonchim", "Retention")
  ]
)

cat("\nSamples with <1000 ASVs:\n")
print(asvs[asvs < 1000])

cat("\nSamples with <10000 reads:\n")
print(reads[reads < 10000])


# ASV summary
cat("\n-------------------------------------\n")
cat("ASV SUMMARY\n")
cat("-------------------------------------\n\n")

cat("ASVs per sample:\n")

print(
  data.frame(
    Sample = names(asvs),
    ASVs = asvs
  )
)

cat("\nASV distribution:\n")
print(summary(asvs))

cat("\nASV abundance distribution:\n")
print(summary(abundance))

cat(
  "\nSingleton ASVs:",
  sum(abundance == 1),
  "\n"
)

cat(
  "ASVs represented by singletons (%):",
  round(
    100 * sum(abundance == 1) / length(abundance),
    2
  ),
  "\n\n"
)


# ASV lengths
cat("-------------------------------------\n")
cat("ASV LENGTHS\n")
cat("-------------------------------------\n\n")

cat("Length distribution:\n")
print(table(lengths))

cat(
  "\nReads from ASVs <",
  expected_min_asv_length,
  " bp:",
  reads_short,
  "\n",
  sep = ""
)

cat(
  "Percentage of reads from ASVs <",
  expected_min_asv_length,
  " bp: ",
  round(percent_reads_short, 2),
  "%\n",
  sep = ""
)


# Taxonomy
cat("\n-------------------------------------\n")
cat("TAXONOMIC ASSIGNMENT\n")
cat("-------------------------------------\n\n")

cat("Assigned taxa per rank:\n")
print(assigned)

cat("\nPercentage assigned:\n")
print(assigned_percent)

cat("\nPhyla with highest number of ASVs:\n")
print(head(phylum, 20))

cat("\nFamilies with highest number of ASVs:\n")
print(head(family, 20))

sink()


#####################################################################################
# End QC
#####################################################################################
